<template><view class="reset-page"><view class="nav"><text @tap="back">‹</text><text>找回支付密码</text><view/></view><view class="body"><view class="shield">✓</view><text class="title">验证银行卡以找回密码</text><text class="copy">为保障资金安全，请完成以下验证</text><view class="form"><view><text>姓名</text><input value="*希" disabled/></view><view @tap="chooseCard"><text>银行卡</text><input :value="`${selected.bank} 尾号（${selected.tail}）`" disabled/><text class="arrow">›</text></view><view><text>安全验证码</text><input v-model="code" type="number" maxlength="6" placeholder="请输入验证码"/><text class="send" @tap="sendCode">{{countdown?`${countdown}s`:'获取验证码'}}</text></view></view><button :disabled="code.length!==6" @tap="confirm">确认</button></view></view></template>
<script setup>import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{enforcePortal}from'../../core/route-guard';import{wallet}from'../../services/wallet';const code=ref(''),selectedIndex=ref(0),countdown=ref(0);let timer;onMounted(()=>enforcePortal('agent'));onBeforeUnmount(()=>clearInterval(timer));const selected=computed(()=>wallet.cards[selectedIndex.value]);function back(){uni.navigateBack()}function chooseCard(){uni.showActionSheet({itemList:wallet.cards.map(x=>`${x.bank}（尾号${x.tail}）`),success:r=>selectedIndex.value=r.tapIndex})}function sendCode(){if(countdown.value)return;countdown.value=60;timer=setInterval(()=>{countdown.value--;if(!countdown.value)clearInterval(timer)},1000);uni.showToast({title:'验证码已发送（演示码：123456）',icon:'none'})}function confirm(){if(code.value!=='123456'){uni.showToast({title:'验证码错误',icon:'none'});return}uni.showToast({title:'请重新设置支付密码',icon:'success'});setTimeout(back,800)}</script>
<style lang="scss" scoped>.reset-page{min-height:100vh;background:#f7f8fc;color:#28334c}.nav{display:flex;justify-content:space-between;align-items:center;height:calc(102rpx + env(safe-area-inset-top));padding:env(safe-area-inset-top) 32rpx 0;background:#fff;box-sizing:border-box;font-size:30rpx;font-weight:720}.nav text:first-child{width:60rpx;color:#5966f3;font-size:60rpx;line-height:1}.nav view{width:60rpx}.body{padding:85rpx 54rpx}.shield{display:flex;align-items:center;justify-content:center;width:86rpx;height:86rpx;margin:auto;border-radius:28rpx;background:#e5e8ff;color:#5966f3;font-size:46rpx;font-weight:750}.title,.copy{display:block;text-align:center}.title{margin-top:30rpx;font-size:36rpx;font-weight:750}.copy{margin-top:14rpx;color:#919baa;font-size:22rpx}.form{margin-top:55rpx;padding:7rpx 30rpx 18rpx;border-radius:25rpx;background:#fff}.form>view{position:relative;display:flex;align-items:center;padding:24rpx 0;border-bottom:1rpx solid #eceef3}.form>view:last-child{border:0}.form>view>text:first-child{width:126rpx;font-size:25rpx;font-weight:650}.form input{flex:1;height:48rpx;color:#68748b;font-size:24rpx}.arrow,.send{position:absolute!important;right:0!important;width:auto!important;color:#5966f3;font-size:22rpx!important;font-weight:400!important}.arrow{font-size:38rpx!important}.body button{width:100%;margin-top:42rpx;border:0;border-radius:16rpx;background:#5966f3;color:#fff;font-size:27rpx;line-height:88rpx}.body button[disabled]{background:#c6cbd8}.body button::after{border:0}</style>
